// These constants represent the RISC-V ELF and the image ID generated by risc0-build.
// The ELF is used for proving and the ID is used for verification.
use elf::{endian::LittleEndian, ElfBytes};
use methods::METHOD_ELF;
use risc0_zkvm::{default_executor, ExecutorEnv};

// Load the input file at compile time using include_bytes macro
const DYLIB_ELF: &[u8] = include_bytes!("../../dylib/out/lib.o");

fn main() {
    // Initialize tracing. In order to view logs, run `RUST_LOG=info cargo run`
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::filter::EnvFilter::from_default_env())
        .init();

    let elf = ElfBytes::<LittleEndian>::minimal_parse(&DYLIB_ELF).expect("Failed to parse elf");

    // Iterate through the sections to find .text
    let text_section_header = elf
        .section_header_by_name(".text")
        .expect("section table should be parseable")
        .expect("file should have a .text section");

    // Get the data at the .text section (the actual riscv code)
    let (dylib_text, _) = elf
        .section_data(&text_section_header)
        .expect("failed to get .text data");

    let env = ExecutorEnv::builder()
        .write_frame(&dylib_text)
        .build()
        .unwrap();

    // Obtain the default prover.
    let executor = default_executor();

    // Proof information by proving the specified ELF binary.
    // This struct contains the receipt along with statistics about execution of the guest
    let prove_info = executor.execute(env, METHOD_ELF).unwrap();

    println!("Journal: {:#?}", prove_info.journal);
}
